widget.solution:
from sklearn.tree import DecisionTreeClassifier

def leaves_at_alpha(X, y, alpha):
    model = DecisionTreeClassifier(ccp_alpha=alpha, random_state=0).fit(X, y)
    return int(model.get_n_leaves())
